28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
39	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        List<String> missingFields = new ArrayList<>();
112	        if (isBlank(ownerFieldsDto.getFirstName())) {
113	            missingFields.add("firstName");
114	        }
115	        if (isBlank(ownerFieldsDto.getLastName())) {
116	            missingFields.add("lastName");
117	        }
118	        if (isBlank(ownerFieldsDto.getAddress())) {
119	            missingFields.add("address");
120	        }
121	        if (isBlank(ownerFieldsDto.getCity())) {
122	            missingFields.add("city");
123	        }
124	        if (isBlank(ownerFieldsDto.getTelephone())) {
125	            missingFields.add("telephone");
126	        }
127	        if (!missingFields.isEmpty()) {
128	            throw new InvalidOwnerFieldsException(missingFields);
129	        }
130	        // Normalize the telephone into E.164 form; a number that cannot form a valid
131	        // E.164 value is rejected with a 400.
132	        String normalizedTelephone = toE164(ownerFieldsDto.getTelephone());
133	        // Email is optional; when present it must be a syntactically valid address and is
134	        // stored lower-cased. An invalid address is rejected with a 400.
135	        String normalizedEmail = normalizeEmail(ownerFieldsDto.getEmail());
136	        // Reject the request if the E.164 telephone is already used by any other owner.
137	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
138	            .map(Owner::getTelephone)
139	            .filter(existing -> existing != null)
140	            .anyMatch(normalizedTelephone::equals);
141	        if (telephoneInUse) {
142	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
143	        }
144	        // Household handling for a matching last name + address (compared case-insensitively with
145	        // collapsed whitespace). By default such a request is rejected as a duplicate household;
146	        // when the caller opts in via 'sharesHousehold' the owner is instead admitted into the shared
147	        // household and every member (the new owner and any existing ones) is stamped with the same
148	        // stable 'householdId'.
149	        String normalizedLastName = collapse(ownerFieldsDto.getLastName());
150	        String normalizedAddress = collapse(ownerFieldsDto.getAddress());
151	        String householdId = null;
152	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
153	            householdId = householdId(normalizedLastName, normalizedAddress);
154	            // Backfill the shared identifier onto any existing member of this household so the whole
155	            // household carries the same stable value.
156	            for (Owner existing : this.clinicService.findAllOwners()) {
157	                if (collapse(existing.getLastName()).equals(normalizedLastName)
158	                    && collapse(existing.getAddress()).equals(normalizedAddress)
159	                    && !householdId.equals(existing.getHouseholdId())) {
160	                    existing.setHouseholdId(householdId);
161	                    this.clinicService.saveOwner(existing);
162	                }
163	            }
164	        } else {
165	            boolean householdInUse = this.clinicService.findAllOwners().stream()
166	                .anyMatch(existing -> collapse(existing.getLastName()).equals(normalizedLastName)
167	                    && collapse(existing.getAddress()).equals(normalizedAddress));
168	            if (householdInUse) {
169	                throw new DuplicateOwnerHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
170	            }
171	        }
172	        HttpHeaders headers = new HttpHeaders();
173	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
174	        owner.setTelephone(normalizedTelephone);
175	        owner.setEmail(normalizedEmail);
176	        owner.setHouseholdId(householdId);
177	        // When no registration date is supplied, default it to the server's current date.
178	        if (owner.getRegistrationDate() == null) {
179	            owner.setRegistrationDate(LocalDate.now());
180	        }
181	        // Assign the customer code: '<LAST3>-<NNNN>' where LAST3 is the upper-cased first three
182	        // letters of the last name and NNNN is a global 4-digit zero-padded sequence equal to one
183	        // more than the current number of owners.
184	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
185	        this.clinicService.saveOwner(owner);
186	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
187	        headers.setLocation(UriComponentsBuilder.newInstance()
188	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
189	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
195	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
196	        if (currentOwner == null) {
197	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	        }
199	        currentOwner.setAddress(ownerFieldsDto.getAddress());
200	        currentOwner.setCity(ownerFieldsDto.getCity());
201	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
202	        currentOwner.setLastName(ownerFieldsDto.getLastName());
203	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
204	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
205	        this.clinicService.saveOwner(currentOwner);
206	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
207	    }
208	
209	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
210	    @Transactional
211	    @Override
212	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
213	        Owner owner = this.clinicService.findOwnerById(ownerId);
214	        if (owner == null) {
215	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
216	        }
217	        this.clinicService.deleteOwner(owner);
218	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
224	        Owner owner = this.clinicService.findOwnerById(ownerId);
225	        if (owner == null) {
226	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	        }
228	        HttpHeaders headers = new HttpHeaders();
229	        Pet pet = petMapper.toPet(petFieldsDto);
230	        owner.setId(ownerId);
231	        pet.setOwner(owner);
232	        pet.getType().setName(null);
233	        this.clinicService.savePet(pet);
234	        PetDto petDto = petMapper.toPetDto(pet);
235	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
236	            .buildAndExpand(pet.getId()).toUri());
237	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
238	    }
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
243	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
244	        if (currentOwner != null) {
245	            Pet currentPet = this.clinicService.findPetById(petId);
246	            if (currentPet != null) {
247	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
248	                currentPet.setName(petFieldsDto.getName());
249	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
250	                this.clinicService.savePet(currentPet);
251	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
252	            }
253	        }
254	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
255	    }
256	
257	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
258	    @Override
259	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
260	        HttpHeaders headers = new HttpHeaders();
261	        Visit visit = visitMapper.toVisit(visitFieldsDto);
262	        Pet pet = new Pet();
263	        pet.setId(petId);
264	        visit.setPet(pet);
265	        this.clinicService.saveVisit(visit);
266	        VisitDto visitDto = visitMapper.toVisitDto(visit);
267	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
268	            .buildAndExpand(visit.getId()).toUri());
269	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
270	    }
271	
272	
273	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
274	    @Override
275	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
276	        Owner owner = this.clinicService.findOwnerById(ownerId);
277	        if (owner != null) {
278	            Pet pet = owner.getPet(petId);
279	            if (pet != null) {
280	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
281	            }
282	        }
283	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
284	    }
285	
286	    private static boolean isBlank(String value) {
287	        return value == null || value.trim().isEmpty();
288	    }
289	
290	    /**
291	     * Normalize an owner identity field for household-duplicate comparison: trim, collapse every
292	     * run of whitespace to a single space, and lower-case. Used so that last name and address are
